import fitz
for i in [2]:
    doc=fitz.open(f'/root/paper{i}.pdf')
    for pno in [1]:
        page=doc[pno]
        d=page.get_text('dict')
        blocks=[]
        for b in d['blocks']:
            if b['type']!=0:
                continue
            text=''.join(''.join(span['text'] for span in line['spans']) for line in b['lines']).strip()
