            print(f'Y={bbox[1]:.1f} size={size:.1f} text={text[:120]}')
        print('bottom:')
        for bbox,size,text in sorted(blocks, key=lambda x: x[0][1])[-5:]:
            print(f'Y={bbox[1]:.1f} size={size:.1f} text={text[:120]}')
        print('---')
